#include "physics/CCPhysicsRayCast.h"
#if CC_USE_PHYSICS

#include <cmath>
#include <algorithm>
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsWorld.h"
#include "physics/CCPhysicsHelper.h"

NS_CC_BEGIN

namespace
{
    // Chipmunk-style filter semantics applied on top of the broad query:
    // shapes sharing a non-zero group never collide, otherwise both
    // category/mask tests must pass.
    bool rayCastPassesFilter(const RayCastInput& input, PhysicsShape* shape)
    {
        if (shape == nullptr)
        {
            return false;
        }

        if (input.groupFilter != 0 && shape->getGroup() == input.groupFilter)
        {
            return false;
        }

        if ((static_cast<unsigned int>(shape->getCategoryBitmask()) & input.collisionMask) == 0)
        {
            return false;
        }

        if ((input.categoryMask & static_cast<unsigned int>(shape->getCollisionBitmask())) == 0)
        {
            return false;
        }

        return true;
    }

    // Context used by PhysicsRayCast::rayCastAllCallback.
    struct RayCastAllContext
    {
        RayCastHit* hits;
        int maxHits;
        int count;
    };

    void fillRayCastHit(PhysicsShape* shape, const Vec2& point, const Vec2& normal,
                        float alpha, const Vec2& origin, float maxDistance, RayCastHit* outHit)
    {
        outHit->shape = shape;
        outHit->body = shape != nullptr ? shape->getBody() : nullptr;
        outHit->point = point;
        outHit->normal = normal;
        outHit->fraction = alpha;
        outHit->distance = alpha * maxDistance;
        (void)origin;
    }
}

PhysicsRayCast::PhysicsRayCast()
: _world(nullptr)
, _space(nullptr)
, _defaultCategoryMask(0xFFFFFFFF)
, _defaultCollisionMask(0xFFFFFFFF)
, _defaultGroup(0)
, _maxDistance(10000.0f)
, _initialized(false)
{
}

PhysicsRayCast::~PhysicsRayCast()
{
}

bool PhysicsRayCast::init(PhysicsWorld* world)
{
    if (world == nullptr)
    {
        return false;
    }

    _world = world;

    // Resolve the underlying cpSpace from any simulated body. It is fine for
    // the space to stay null on an empty world: every query falls back to the
    // PhysicsWorld public API in that case.
    _space = nullptr;
    for (auto body : world->getAllBodies())
    {
        if (body != nullptr && body->getCPBody() != nullptr)
        {
            cpSpace* space = cpBodyGetSpace(body->getCPBody());
            if (space != nullptr)
            {
                _space = space;
                break;
            }
        }
    }

    _initialized = true;
    return true;
}

bool PhysicsRayCast::rayCastFirst(const RayCastInput& input, RayCastHit* outHit)
{
    if (!_initialized || _world == nullptr)
    {
        return false;
    }

    Vec2 dir = input.direction;
    float length = dir.getLength();
    if (length <= 0.0f)
    {
        return false;
    }
    dir = dir / length;

