    Vec2 dir = input.direction;
    float length = dir.getLength();
    if (length <= 0.0f)
    {
        return 0;
    }
    dir = dir / length;

    float maxDistance = input.maxDistance > 0.0f ? input.maxDistance : _maxDistance;
    Vec2 end = input.origin + dir * maxDistance;

    std::vector<RayCastHit> collected;

    PhysicsRayCastCallbackFunc func = [&](PhysicsWorld& /*world*/, const PhysicsRayCastInfo& info, void* /*data*/) -> bool
    {
        if (rayCastPassesFilter(input, info.shape))
        {
            RayCastHit hit;
            fillRayCastHit(info.shape, info.contact, info.normal, info.fraction,
                           input.origin, maxDistance, &hit);
            collected.push_back(hit);
        }
        return true;
    };
    _world->rayCast(func, input.origin, end, nullptr);

    std::sort(collected.begin(), collected.end(),
              [](const RayCastHit& a, const RayCastHit& b) { return a.fraction < b.fraction; });

    int count = std::min(static_cast<int>(collected.size()), maxHits);
    for (int i = 0; i < count; ++i)
    {
        outHits[i] = collected[i];
    }
    return count;
}

