{
    if (outHits == nullptr || maxHits <= 0 || numRays <= 0)
    {
        return 0;
    }

    float baseAngle = std::atan2(direction.y, direction.x);
    float halfFan = angle * 0.5f;

    int count = 0;
    for (int i = 0; i < numRays && count < maxHits; ++i)
    {
        float t = numRays > 1 ? static_cast<float>(i) / static_cast<float>(numRays - 1) : 0.5f;
        float rayAngle = baseAngle - halfFan + angle * t;

        RayCastInput input;
        input.origin = origin;
        input.direction = Vec2(std::cos(rayAngle), std::sin(rayAngle));
        input.maxDistance = maxDistance;
        input.categoryMask = _defaultCategoryMask;
        input.collisionMask = _defaultCollisionMask;
        input.groupFilter = _defaultGroup;

        RayCastHit hit;
        if (rayCastFirst(input, &hit))
